import React, { useEffect, useState } from "react";
import { fetchDocs, deleteDoc, createDoc, shareDoc } from "../api/docs";
import { useNavigate } from "react-router-dom";
import { useAuth } from "../App";

export default function DocumentList() {
  const { user, logout } = useAuth();
  const [docs, setDocs] = useState([]);
  const [title, setTitle] = useState("");
  const [content, setContent] = useState("");
  const [type, setType] = useState("rich");
  const [shareEmail, setShareEmail] = useState("");
  const [shareDocId, setShareDocId] = useState(null);
  const nav = useNavigate();

  async function load() {
    try {
      setDocs(await fetchDocs());
    } catch {
      alert("Kunde inte hämta dokument.");
    }
  }
  useEffect(() => { load(); }, []);

  async function create(e) {
    e.preventDefault();
    if (!title) return;
    await createDoc(title, content, type);
    setTitle(""); setContent(""); setType("rich");
    load();
  }

  async function share() {
    if (!shareDocId || !shareEmail) return;
    try {
      await shareDoc(shareDocId, shareEmail);
      alert("Delning initierad (inbjudan skickad eller direkt delad).");
      setShareDocId(null); setShareEmail("");
      load();
    } catch {
      alert("Kunde inte dela dokument.");
    }
  }

  return (
    <div style={{ padding: "2rem", maxWidth: "800px", margin: "auto" }}>
      <div style={{ display: "flex", justifyContent: "space-between" }}>
        <h1>📄 Mina dokument</h1>
        <div>
          <span style={{ marginRight: 10 }}>{user?.email}</span>
          <button onClick={logout}>Logga ut</button>
        </div>
      </div>

      <form onSubmit={create} style={{ margin: "1rem 0" }}>
        <input placeholder="Titel" value={title} onChange={(e)=>setTitle(e.target.value)} />
        <input placeholder="Innehåll" value={content} onChange={(e)=>setContent(e.target.value)} />
        <select value={type} onChange={(e)=>setType(e.target.value)} style={{ marginLeft: 8 }}>
          <option value="rich">Text</option>
          <option value="code">Code-mode</option>
        </select>
        <button type="submit" style={{ marginLeft: 8 }}>Skapa</button>
      </form>

      {docs.length === 0 && <p>Inga dokument än.</p>}

      <ul style={{ listStyle: "none", padding: 0 }}>
        {docs.map((d) => (
          <li key={d.id} style={{ borderBottom: "1px solid #ccc", padding: "1rem 0" }}>
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
              <div>
                <h3 style={{ margin: 0 }}>{d.title} {d.type === "code" ? <small> (code)</small> : null}</h3>
                <small>Ägare: {d.ownerId === (user?.id) ? "Du" : d.ownerId}</small>
              </div>
              <div>
                <button onClick={() => nav(`/doc/${d.id}`)}>Öppna</button>
                <button onClick={async()=>{ if(window.confirm("Radera?")) { await deleteDoc(d.id); load(); }}} style={{ marginLeft: 8 }}>Radera</button>
                <button onClick={()=>setShareDocId(d.id)} style={{ marginLeft: 8 }}>Dela</button>
              </div>
            </div>
            {shareDocId === d.id && (
              <div style={{ marginTop: 8 }}>
                <input placeholder="E-post att bjuda in" value={shareEmail} onChange={(e)=>setShareEmail(e.target.value)} />
                <button onClick={share} style={{ marginLeft: 8 }}>Skicka inbjudan</button>
                <button onClick={()=>{ setShareDocId(null); setShareEmail(""); }} style={{ marginLeft: 8 }}>Avbryt</button>
              </div>
            )}
          </li>
        ))}
      </ul>
    </div>
  );
}
