import React, { useState } from "react";
import { loginAndStore } from "../api/auth";
import { useNavigate, Link } from "react-router-dom";

export default function Login({ onLogin }) {
  const nav = useNavigate();
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  async function submit(e) {
    e.preventDefault();
    try {
      const user = await loginAndStore({ email, password });
      onLogin(user);
      nav("/");
    } catch (e) {
      alert("Inloggning misslyckades.");
    }
  }
  return (
    <div style={{ padding: 20, maxWidth: 400, margin: "0 auto" }}>
      <h2>Logga in</h2>
      <form onSubmit={submit}>
        <input placeholder="E-post" value={email} onChange={(e)=>setEmail(e.target.value)} />
        <input type="password" placeholder="Lösenord" value={password} onChange={(e)=>setPassword(e.target.value)} />
        <button type="submit">Logga in</button>
      </form>
      <p>Ingen användare? <Link to="/register">Registrera</Link></p>
    </div>
  );
}
