import React, { useEffect, useRef, useState } from "react";
import { useParams, Link } from "react-router-dom";
import { fetchDoc, updateDoc, addComment, execCode } from "../api/docs";
import { useAuth } from "../App";
import { io } from "socket.io-client";
import { EditorView, basicSetup } from "codemirror";
import { EditorState } from "@codemirror/state";
import { javascript } from "@codemirror/lang-javascript";

const API_URL =
  process.env.REACT_APP_API_URL ||
  (window.location.hostname.includes("localhost")
    ? "http://localhost:3000"
    : "https://ssr-editor-a4f5aqbafhaedmhp.swedencentral-01.azurewebsites.net");

export default function DocumentEditor() {
  const { id } = useParams();
  const { user } = useAuth();
  const [doc, setDoc] = useState(null);
  const [title, setTitle] = useState("");
  const [content, setContent] = useState("");
  const [type, setType] = useState("rich");
  const [newComment, setNewComment] = useState({ line: "", text: "" });
  const [execResult, setExecResult] = useState(null);

  const socketRef = useRef(null);
  const editorRef = useRef(null);
  const viewRef = useRef(null);

  useEffect(() => {
    (async () => {
      const d = await fetchDoc(id);
      setDoc(d);
      setTitle(d.title);
      setContent(d.content);
      setType(d.type);

      // init CodeMirror om code-mode
      if (d.type === "code" && !viewRef.current) {
        const state = EditorState.create({
          doc: d.content || "",
          extensions: [basicSetup, javascript(), EditorView.updateListener.of((v) => {
            if (v.docChanged) {
              const value = v.state.doc.toString();
              setContent(value);
              socketRef.current?.emit("editDoc", { docId: id, patch: { content: value } });
            }
          })]
        });
        viewRef.current = new EditorView({ state, parent: editorRef.current });
      }
    })();
  }, [id]);

  // Sockets
  useEffect(() => {
    const token = localStorage.getItem("token");
    const socket = io(API_URL, { auth: { token } });
    socketRef.current = socket;
    socket.on("connect", () => { socket.emit("joinDoc", { docId: id }); });
    socket.on("docPatched", ({ patch }) => {
      if (type === "code" && viewRef.current && patch.content !== undefined) {
        const current = viewRef.current.state.doc.toString();
        if (current !== patch.content) {
          viewRef.current.dispatch({
            changes: { from: 0, to: current.length, insert: patch.content }
          });
        }
      } else if (patch.content !== undefined) {
        setContent(patch.content);
      }
    });
    socket.on("commentAdded", ({ comment }) => {
      setDoc((prev) => ({ ...prev, comments: [...(prev?.comments||[]), comment] }));
    });
    return () => {
      socket.emit("leaveDoc", { docId: id });
      socket.disconnect();
    };
  }, [id, type]);

  async function save() {
    await updateDoc(id, title, content, type);
    alert("Sparat!");
  }

  async function addCommentSubmit(e) {
    e.preventDefault();
    const lineNum = newComment.line ? parseInt(newComment.line, 10) : null;
    const { comment } = await addComment(id, { line: isNaN(lineNum) ? null : lineNum, text: newComment.text });
    setDoc((d) => ({ ...d, comments: [...(d?.comments || []), comment] }));
    setNewComment({ line: "", text: "" });
    // skicka över socket också för live-uppdatering
    socketRef.current?.emit("addComment", { docId: id, comment });
  }

  async function runCode() {
    try {
      const out = await execCode(content);
      setExecResult(out);
    } catch {
      setExecResult({ error: "Körning misslyckades" });
    }
  }

  return (
    <div style={{ padding: 16 }}>
      <div style={{ display: "flex", justifyContent: "space-between" }}>
        <Link to="/">← Tillbaka</Link>
        <div>{user?.email}</div>
      </div>

      <h2>Redigera dokument</h2>

      <div style={{ marginBottom: 8 }}>
        <input value={title} onChange={(e)=>setTitle(e.target.value)} placeholder="Titel" />
        <select value={type} onChange={(e)=>setType(e.target.value)} style={{ marginLeft: 8 }}>
          <option value="rich">Text</option>
          <option value="code">Code-mode</option>
        </select>
        <button onClick={save} style={{ marginLeft: 8 }}>Spara</button>
        {type === "code" && <button onClick={runCode} style={{ marginLeft: 8 }}>Kör kod</button>}
      </div>

      {type === "code" ? (
        <>
          <div ref={editorRef} style={{ border: "1px solid #ccc", borderRadius: 6 }} />
          <div style={{ marginTop: 12 }}>
            <h3>Resultat</h3>
            <pre style={{ background: "#f6f8fa", padding: 8, borderRadius: 6 }}>
              {execResult ? JSON.stringify(execResult, null, 2) : "Ingen körning än."}
            </pre>
          </div>
        </>
      ) : (
        <textarea
          style={{ width: "100%", minHeight: 300 }}
          value={content}
          onChange={(e)=>{
            setContent(e.target.value);
            socketRef.current?.emit("editDoc", { docId: id, patch: { content: e.target.value }});
          }}
        />
      )}

      <div style={{ display: "flex", gap: 24, marginTop: 16 }}>
        <form onSubmit={addCommentSubmit} style={{ maxWidth: 400 }}>
          <h3>Lägg till kommentar</h3>
          <input placeholder="Rad (valfritt)" value={newComment.line} onChange={(e)=>setNewComment(s=>({...s, line: e.target.value}))} />
          <textarea placeholder="Kommentar" value={newComment.text} onChange={(e)=>setNewComment(s=>({...s, text: e.target.value}))} />
          <button type="submit">Kommentera</button>
        </form>

        <div>
          <h3>Kommentarer</h3>
          <ul>
            {(doc?.comments || []).map(c => (
              <li key={c._id}>
                <b>Rad {c.line ?? "-"}</b>: {c.text} <small>({c.authorId})</small>
              </li>
            ))}
          </ul>
        </div>
      </div>
    </div>
  );
}
